namespace ContosoUniversity.Tests.Controllers
{
    public class HomeControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly HomeController _controller;

        public HomeControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new HomeController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsView()
        {
            var result = _controller.Index();

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void About_ReturnsViewWithEnrollmentGroups()
        {
            _context.Students.Add(new Student
            {
                FirstMidName = "Alice",
                LastName = "Smith",
                EnrollmentDate = new DateTime(2023, 9, 1)
            });
            _context.Students.Add(new Student
            {
                FirstMidName = "Bob",
                LastName = "Jones",
                EnrollmentDate = new DateTime(2023, 9, 1)
            });
            _context.Students.Add(new Student
            {
                FirstMidName = "Charlie",
                LastName = "Brown",
                EnrollmentDate = new DateTime(2022, 9, 1)
            });
            _context.SaveChanges();

            var result = _controller.About() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<System.Collections.Generic.List<EnrollmentDateGroup>>(result.Model);
            Assert.Equal(2, model.Count);

            var group2023 = model.Single(g => g.EnrollmentDate == new DateTime(2023, 9, 1));
            Assert.Equal(2, group2023.StudentCount);

            var group2022 = model.Single(g => g.EnrollmentDate == new DateTime(2022, 9, 1));
            Assert.Equal(1, group2022.StudentCount);
        }

        [Fact]
        public void About_NoStudents_ReturnsEmptyList()
        {
            var result = _controller.About() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<System.Collections.Generic.List<EnrollmentDateGroup>>(result.Model);
            Assert.Empty(model);
        }

        [Fact]
        public void Contact_ReturnsViewWithMessage()
        {
            var result = _controller.Contact() as ViewResult;

            Assert.NotNull(result);
            Assert.Equal("Your contact page.", _controller.ViewBag.Message);
        }

        [Fact]
        public void Error_ReturnsView()
        {
            var result = _controller.Error();

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void Unauthorized_ReturnsViewWithMessage()
        {
            var result = _controller.Unauthorized() as ViewResult;

            Assert.NotNull(result);
            Assert.Contains("permission", (string)_controller.ViewBag.Message);
        }
    }
}

using System;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new NotificationsController(_context);

            // Drain the static notification queue to isolate tests
            using var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
        {
            var result = _controller.GetNotifications();

            Assert.NotNull(result);
            var json = result.Value;
            Assert.NotNull(json);
            // Use dynamic to access anonymous type properties
            var successProp = json.GetType().GetProperty("success");
            var countProp = json.GetType().GetProperty("count");
            Assert.True((bool)successProp.GetValue(json));
            Assert.Equal(0, (int)countProp.GetValue(json));
        }

        [Fact]
        public void GetNotifications_WithMessages_ReturnsNotifications()
        {
            // Enqueue via the service
            using var svc = new NotificationService();
            svc.SendNotification("Student", "1", "Test Student", EntityOperation.CREATE, "admin");
            svc.SendNotification("Course", "2", "Test Course", EntityOperation.UPDATE, "admin");

            var result = _controller.GetNotifications();

            var json = result.Value;
            var countProp = json.GetType().GetProperty("count");
            var count = (int)countProp.GetValue(json);
            Assert.Equal(2, count);
        }

        [Fact]
        public void GetNotifications_CapsAtTen()
        {
            using var svc = new NotificationService();
            for (int i = 0; i < 15; i++)
            {
                svc.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
            }

            var result = _controller.GetNotifications();

            var json = result.Value;
            var countProp = json.GetType().GetProperty("count");
            Assert.Equal(10, (int)countProp.GetValue(json));
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccess()
        {
            var result = _controller.MarkAsRead(1);

            var json = result.Value;
            var successProp = json.GetType().GetProperty("success");
            Assert.True((bool)successProp.GetValue(json));
        }

        [Fact]
        public void Index_ReturnsView()
        {
            var result = _controller.Index();

            Assert.IsType<ViewResult>(result);
        }
    }
}

using System;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut;

        public NotificationServiceTests()
        {
            _sut = new NotificationService();
            // Drain the static queue to isolate tests
            while (_sut.ReceiveNotification() != null) { }
        }

        public void Dispose() => _sut.Dispose();

        [Fact]
        public void SendNotification_WithDisplayName_EnqueuesNotification()
        {
            _sut.SendNotification("Student", "42", "John Doe", EntityOperation.CREATE, "admin");

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
            Assert.Contains("John Doe", notification.Message);
            Assert.Contains("created", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
        {
            _sut.SendNotification("Course", "101", EntityOperation.UPDATE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("ID: 101", notification.Message);
            Assert.Contains("updated", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutUserName_DefaultsToSystem()
        {
            _sut.SendNotification("Department", "5", EntityOperation.DELETE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Theory]
        [InlineData(EntityOperation.CREATE, "created")]
        [InlineData(EntityOperation.UPDATE, "updated")]
        [InlineData(EntityOperation.DELETE, "deleted")]
        public void SendNotification_OperationType_GeneratesCorrectMessage(EntityOperation operation, string expectedVerb)
        {
            _sut.SendNotification("Student", "1", "Test Student", operation, "user1");

            var notification = _sut.ReceiveNotification();

            Assert.Contains(expectedVerb, notification.Message);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToApproximatelyNow()
        {
            var before = DateTime.Now.AddSeconds(-1);
            _sut.SendNotification("Course", "10", EntityOperation.CREATE);
            var after = DateTime.Now.AddSeconds(1);

            var notification = _sut.ReceiveNotification();

            Assert.InRange(notification.CreatedAt, before, after);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            var result = _sut.ReceiveNotification();
            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_MultipleMessages_ReturnsInFifoOrder()
        {
            _sut.SendNotification("A", "1", EntityOperation.CREATE);
            _sut.SendNotification("B", "2", EntityOperation.UPDATE);
            _sut.SendNotification("C", "3", EntityOperation.DELETE);

            var first = _sut.ReceiveNotification();
            var second = _sut.ReceiveNotification();
            var third = _sut.ReceiveNotification();

            Assert.Equal("A", first.EntityType);
            Assert.Equal("B", second.EntityType);
            Assert.Equal("C", third.EntityType);
        }

        [Fact]
        public void ReceiveNotification_DequeuedMessageIsConsumed()
        {
            _sut.SendNotification("Test", "1", EntityOperation.CREATE);

            var first = _sut.ReceiveNotification();
            var second = _sut.ReceiveNotification();

            Assert.NotNull(first);
            Assert.Null(second);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // MarkAsRead is a no-op for in-memory; verify it doesn't throw
            var exception = Record.Exception(() => _sut.MarkAsRead(999));
            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_WithBlankDisplayName_FallsBackToEntityId()
        {
            _sut.SendNotification("Student", "77", "   ", EntityOperation.CREATE, "admin");

            var notification = _sut.ReceiveNotification();

            Assert.Contains("ID: 77", notification.Message);
        }

        [Fact]
        public void SendNotification_WithNullDisplayName_FallsBackToEntityId()
        {
            _sut.SendNotification("Student", "77", null, EntityOperation.CREATE, "admin");

            var notification = _sut.ReceiveNotification();

            Assert.Contains("ID: 77", notification.Message);
        }

        [Fact]
        public void SendNotification_CreateOperation_MessageContainsNew()
        {
            _sut.SendNotification("Course", "10", "Physics", EntityOperation.CREATE);

            var notification = _sut.ReceiveNotification();

            Assert.StartsWith("New", notification.Message);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        [Fact]
        public void Create_FirstPage_ContainsCorrectItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(1, result.First());
            Assert.Equal(10, result.Last());
        }

        [Fact]
        public void Create_SecondPage_ContainsCorrectItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 2, 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(11, result.First());
            Assert.Equal(20, result.Last());
        }

        [Fact]
        public void Create_LastPartialPage_ContainsRemainingItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 3, 10);

            Assert.Equal(5, result.Count);
            Assert.Equal(21, result.First());
            Assert.Equal(25, result.Last());
        }

        [Fact]
        public void TotalPages_CalculatedCorrectly()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(3, result.TotalPages);
        }

        [Fact]
        public void TotalPages_ExactMultiple_NoExtraPage()
        {
            var source = Enumerable.Range(1, 20).AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(2, result.TotalPages);
        }

        [Fact]
        public void HasPreviousPage_FirstPage_ReturnsFalse()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.False(result.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_SecondPage_ReturnsTrue()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 2, 10);

            Assert.True(result.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_MiddlePage_ReturnsTrue()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.True(result.HasNextPage);
        }

        [Fact]
        public void HasNextPage_LastPage_ReturnsFalse()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 3, 10);

            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void PageIndex_ReflectsRequestedPage()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 2, 10);

            Assert.Equal(2, result.PageIndex);
        }

        [Fact]
        public void Create_SingleItem_SinglePage()
        {
            var source = new[] { 42 }.AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Single(result);
            Assert.Equal(1, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Constructor_SetsPropertiesCorrectly()
        {
            var items = new List<string> { "a", "b", "c" };

            var result = new PaginatedList<string>(items, 15, 2, 5);

            Assert.Equal(3, result.Count);
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
            Assert.True(result.HasPreviousPage);
            Assert.True(result.HasNextPage);
        }
    }
}

using ContosoUniversity.Models;
