using System;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new StudentsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Student CreateStudent(string firstName = "John", string lastName = "Doe", DateTime? enrollmentDate = null)
        {
            return new Student
            {
                FirstMidName = firstName,
                LastName = lastName,
                EnrollmentDate = enrollmentDate ?? new DateTime(2023, 9, 1)
            };
        }

        private void SeedStudents(params Student[] students)
        {
            _context.Students.AddRange(students);
            _context.SaveChanges();
        }

        // --- Index ---

        [Fact]
        public void Index_NoParams_ReturnsViewWithStudents()
        {
            SeedStudents(
                CreateStudent("Alice", "Smith"),
                CreateStudent("Bob", "Jones")
            );

            var result = _controller.Index(null, null, null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(2, model.Count);
        }

        [Fact]
        public void Index_DefaultSort_OrdersByLastNameAscending()
        {
            SeedStudents(
                CreateStudent("Bob", "Zebra"),
                CreateStudent("Alice", "Anderson")
            );

            var result = _controller.Index(null, null, null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);

            Assert.Equal("Anderson", model.First().LastName);
            Assert.Equal("Zebra", model.Last().LastName);
        }

        [Fact]
        public void Index_NameDescSort_OrdersByLastNameDescending()
        {
            SeedStudents(
                CreateStudent("Alice", "Anderson"),
                CreateStudent("Bob", "Zebra")
            );

            var result = _controller.Index("name_desc", null, null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);

            Assert.Equal("Zebra", model.First().LastName);
            Assert.Equal("Anderson", model.Last().LastName);
        }

        [Fact]
        public void Index_DateSort_OrdersByEnrollmentDateAscending()
        {
            SeedStudents(
                CreateStudent("Late", "Starter", new DateTime(2023, 9, 1)),
                CreateStudent("Early", "Bird", new DateTime(2020, 1, 1))
            );

            var result = _controller.Index("Date", null, null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);

            Assert.Equal("Bird", model.First().LastName);
            Assert.Equal("Starter", model.Last().LastName);
        }

        [Fact]
        public void Index_DateDescSort_OrdersByEnrollmentDateDescending()
        {
            SeedStudents(
                CreateStudent("Early", "Bird", new DateTime(2020, 1, 1)),
                CreateStudent("Late", "Starter", new DateTime(2023, 9, 1))
            );

            var result = _controller.Index("date_desc", null, null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);

            Assert.Equal("Starter", model.First().LastName);
        }

        [Fact]
        public void Index_SearchByLastName_FiltersResults()
        {
            SeedStudents(
                CreateStudent("Alice", "Smith"),
                CreateStudent("Bob", "Jones"),
                CreateStudent("Charlie", "Smithson")
            );

            var result = _controller.Index(null, null, "Smith", null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);

            Assert.Equal(2, model.Count);
            Assert.All(model, s => Assert.Contains("Smith", s.LastName));
        }

        [Fact]
        public void Index_SearchByFirstName_FiltersResults()
        {
            SeedStudents(
                CreateStudent("Alice", "Smith"),
                CreateStudent("Bob", "Jones")
            );

            var result = _controller.Index(null, null, "Alice", null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);

            Assert.Single(model);
            Assert.Equal("Alice", model.First().FirstMidName);
        }

