using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new StudentsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Student CreateStudent(string firstName = "John", string lastName = "Doe", DateTime? enrollmentDate = null)
        {
            return new Student
            {
                FirstMidName = firstName,
                LastName = lastName,
                EnrollmentDate = enrollmentDate ?? new DateTime(2023, 9, 1)
            };
        }

        private void SeedStudents(params Student[] students)
        {
            _context.Students.AddRange(students);
            _context.SaveChanges();
        }

        // --- Index ---

        [Fact]
        public void Index_NoParams_ReturnsViewWithStudents()
        {
            SeedStudents(
                CreateStudent("Alice", "Smith"),
                CreateStudent("Bob", "Jones")
            );

            var result = _controller.Index(null, null, null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(2, model.Count);
        }

        [Fact]
        public void Index_DefaultSort_OrdersByLastNameAscending()
        {
            SeedStudents(
                CreateStudent("Bob", "Zebra"),
                CreateStudent("Alice", "Anderson")
            );

            var result = _controller.Index(null, null, null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);

            Assert.Equal("Anderson", model.First().LastName);
            Assert.Equal("Zebra", model.Last().LastName);
        }

        [Fact]
        public void Index_NameDescSort_OrdersByLastNameDescending()
        {
            SeedStudents(
                CreateStudent("Alice", "Anderson"),
                CreateStudent("Bob", "Zebra")
            );

            var result = _controller.Index("name_desc", null, null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);

            Assert.Equal("Zebra", model.First().LastName);
            Assert.Equal("Anderson", model.Last().LastName);
        }

        [Fact]
        public void Index_DateSort_OrdersByEnrollmentDateAscending()
        {
            SeedStudents(
                CreateStudent("Late", "Starter", new DateTime(2023, 9, 1)),
                CreateStudent("Early", "Bird", new DateTime(2020, 1, 1))
            );

            var result = _controller.Index("Date", null, null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);

            Assert.Equal("Bird", model.First().LastName);
            Assert.Equal("Starter", model.Last().LastName);
        }

        [Fact]
        public void Index_DateDescSort_OrdersByEnrollmentDateDescending()
        {
            SeedStudents(
                CreateStudent("Early", "Bird", new DateTime(2020, 1, 1)),
                CreateStudent("Late", "Starter", new DateTime(2023, 9, 1))
            );

            var result = _controller.Index("date_desc", null, null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);

            Assert.Equal("Starter", model.First().LastName);
        }

        [Fact]
        public void Index_SearchByLastName_FiltersResults()
        {
            SeedStudents(
                CreateStudent("Alice", "Smith"),
                CreateStudent("Bob", "Jones"),
                CreateStudent("Charlie", "Smithson")
            );

            var result = _controller.Index(null, null, "Smith", null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);

            Assert.Equal(2, model.Count);
            Assert.All(model, s => Assert.Contains("Smith", s.LastName));
        }

        [Fact]
        public void Index_SearchByFirstName_FiltersResults()
        {
            SeedStudents(
                CreateStudent("Alice", "Smith"),
                CreateStudent("Bob", "Jones")
            );

            var result = _controller.Index(null, null, "Alice", null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);

            Assert.Single(model);
            Assert.Equal("Alice", model.First().FirstMidName);
        }

        [Fact]
        public void Index_SearchString_ResetsPageToOne()
        {
            SeedStudents(CreateStudent());

            var result = _controller.Index(null, null, "search", 5) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);

            Assert.Equal(1, model.PageIndex);
        }

        [Fact]
        public void Index_NullSearch_UsesCurrentFilter()
        {
            SeedStudents(
                CreateStudent("Alice", "Smith"),
                CreateStudent("Bob", "Jones")
            );

            var result = _controller.Index(null, "Smith", null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);

            Assert.Single(model);
        }

        [Fact]
        public void Index_SetsViewBagSortParameters()
        {
            SeedStudents(CreateStudent());

            var result = _controller.Index(null, null, null, null) as ViewResult;

            Assert.Equal("name_desc", _controller.ViewBag.NameSortParm);
            Assert.Equal("Date", _controller.ViewBag.DateSortParm);
        }

        [Fact]
        public void Index_WithNameSort_SetsNameSortParmToEmpty()
        {
            SeedStudents(CreateStudent());

            _controller.Index("name_desc", null, null, null);

            Assert.Equal("", _controller.ViewBag.NameSortParm);
        }

        // --- Details ---

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithStudent()
        {
            var student = CreateStudent("Alice", "Smith");
            student.Enrollments = new System.Collections.Generic.List<Enrollment>();
            SeedStudents(student);

            var result = _controller.Details(student.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal("Alice", model.FirstMidName);
            Assert.Equal("Smith", model.LastName);
        }

        // --- Create GET ---

        [Fact]
        public void Create_Get_ReturnsViewWithDefaultDate()
        {
            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(DateTime.Today, model.EnrollmentDate);
        }

        // --- Create POST ---

        [Fact]
        public void Create_ValidStudent_RedirectsToIndex()
        {
            var student = CreateStudent("Test", "Student", new DateTime(2023, 9, 1));

            var result = _controller.Create(student);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Create_ValidStudent_SavesInDatabase()
        {
            var student = CreateStudent("Test", "Student", new DateTime(2023, 9, 1));

            _controller.Create(student);

            Assert.Single(_context.Students);
            Assert.Equal("Test", _context.Students.First().FirstMidName);
        }

        [Fact]
        public void Create_InvalidEnrollmentDate_MinValue_ReturnsView()
        {
            var student = CreateStudent("Test", "Student", DateTime.MinValue);

            var result = _controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.False(_controller.ModelState.IsValid);
        }

        [Fact]
        public void Create_InvalidModelState_ReturnsViewWithStudent()
        {
            _controller.ModelState.AddModelError("LastName", "Required");
            var student = CreateStudent();

            var result = _controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.IsType<Student>(result.Model);
        }

        // --- Edit GET ---

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit((int?)null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_Get_InvalidId_ReturnsNotFound()
        {
            var result = _controller.Edit(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithStudent()
        {
            var student = CreateStudent("Alice", "Smith");
            SeedStudents(student);

            var result = _controller.Edit(student.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal("Alice", model.FirstMidName);
        }

        // --- Edit POST ---

        [Fact]
        public void Edit_ValidStudent_RedirectsToIndex()
        {
            var student = CreateStudent("Alice", "Smith");
            SeedStudents(student);
            _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var updated = new Student
            {
                ID = student.ID,
                FirstMidName = "Updated",
                LastName = "Smith",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var result = _controller.Edit(updated);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_InvalidEnrollmentDate_ReturnsView()
        {
            var student = CreateStudent("Alice", "Smith");
            SeedStudents(student);
            _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var updated = new Student
            {
                ID = student.ID,
                FirstMidName = "Alice",
                LastName = "Smith",
                EnrollmentDate = DateTime.MinValue
            };

            var result = _controller.Edit(updated) as ViewResult;

            Assert.NotNull(result);
        }

        // --- Delete GET ---

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_Get_InvalidId_ReturnsNotFound()
        {
            var result = _controller.Delete(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithStudent()
        {
            var student = CreateStudent("Alice", "Smith");
            SeedStudents(student);

            var result = _controller.Delete(student.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal("Smith", model.LastName);
        }

        // --- DeleteConfirmed ---

        [Fact]
        public void DeleteConfirmed_RemovesStudentAndRedirects()
        {
            var student = CreateStudent("Alice", "Smith");
            SeedStudents(student);
            var id = student.ID;

            var result = _controller.DeleteConfirmed(id);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Empty(_context.Students);
        }
    }
}
