using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests.Models
{
    public class ModelTests
    {
        [Theory]
        [InlineData("Smith", "John", "Smith, John")]
        [InlineData("Doe", "Jane", "Doe, Jane")]
        [InlineData("O'Brien", "Mary", "O'Brien, Mary")]
        public void Person_FullName_ConcatenatesLastCommaFirst(string lastName, string firstName, string expected)
        {
            var student = new Student { LastName = lastName, FirstMidName = firstName };
            Assert.Equal(expected, student.FullName);
        }

        [Fact]
        public void Instructor_FullName_WorksSameAsPerson()
        {
            var instructor = new Instructor { LastName = "Kim", FirstMidName = "Abercrombie" };
            Assert.Equal("Kim, Abercrombie", instructor.FullName);
        }

        [Fact]
        public void ErrorViewModel_ShowRequestId_TrueWhenSet()
        {
            var model = new ErrorViewModel { RequestId = "abc123" };
            Assert.True(model.ShowRequestId);
        }

        [Theory]
        [InlineData(null)]
        [InlineData("")]
        public void ErrorViewModel_ShowRequestId_FalseWhenNullOrEmpty(string requestId)
        {
            var model = new ErrorViewModel { RequestId = requestId };
            Assert.False(model.ShowRequestId);
        }

        [Fact]
        public void Course_Properties_SetCorrectly()
        {
            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1,
                TeachingMaterialImagePath = "/uploads/test.jpg"
            };

            Assert.Equal(1050, course.CourseID);
            Assert.Equal("Chemistry", course.Title);
            Assert.Equal(3, course.Credits);
            Assert.Equal(1, course.DepartmentID);
            Assert.Equal("/uploads/test.jpg", course.TeachingMaterialImagePath);
        }

        [Fact]
        public void Department_Properties_SetCorrectly()
        {
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 350000m,
                InstructorID = 5
            };

            Assert.Equal(1, dept.DepartmentID);
            Assert.Equal("Engineering", dept.Name);
            Assert.Equal(350000m, dept.Budget);
            Assert.Equal(5, dept.InstructorID);
        }

        [Fact]
        public void Department_InstructorID_IsNullable()
        {
            var dept = new Department { Name = "Test" };
            Assert.Null(dept.InstructorID);
        }

        [Fact]
        public void Enrollment_Grade_IsNullable()
        {
            var enrollment = new Enrollment { EnrollmentID = 1, CourseID = 1, StudentID = 1 };
            Assert.Null(enrollment.Grade);
        }

        [Theory]
        [InlineData(Grade.A)]
        [InlineData(Grade.B)]
        [InlineData(Grade.C)]
        [InlineData(Grade.D)]
        [InlineData(Grade.F)]
        public void Enrollment_Grade_CanBeSetToAnyValue(Grade grade)
        {
            var enrollment = new Enrollment { Grade = grade };
            Assert.Equal(grade, enrollment.Grade);
        }

        [Fact]
        public void Notification_Properties_SetCorrectly()
        {
            var now = System.DateTime.Now;
            var notification = new Notification
            {
                Id = 1,
                EntityType = "Student",
                EntityId = "42",
                Operation = "CREATE",
                Message = "Created",
                CreatedAt = now,
                CreatedBy = "admin",
                IsRead = false
            };

            Assert.Equal(1, notification.Id);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("Created", notification.Message);
            Assert.Equal(now, notification.CreatedAt);
            Assert.Equal("admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
            Assert.Null(notification.ReadAt);
        }

        [Fact]
        public void CourseAssignment_Properties_SetCorrectly()
        {
            var ca = new CourseAssignment { CourseID = 101, InstructorID = 5 };
            Assert.Equal(101, ca.CourseID);
            Assert.Equal(5, ca.InstructorID);
        }

        [Fact]
        public void OfficeAssignment_Properties_SetCorrectly()
        {
            var oa = new OfficeAssignment { InstructorID = 3, Location = "Room 101" };
            Assert.Equal(3, oa.InstructorID);
            Assert.Equal("Room 101", oa.Location);
        }
    }
}

