using System;
using System.IO;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;
        private readonly Mock<IWebHostEnvironment> _envMock;
        private readonly Mock<ILogger<CoursesController>> _loggerMock;
        private readonly string _tempDir;

        public CoursesControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _envMock = new Mock<IWebHostEnvironment>();
            _loggerMock = new Mock<ILogger<CoursesController>>();
            _tempDir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
            Directory.CreateDirectory(_tempDir);
            _envMock.Setup(e => e.WebRootPath).Returns(_tempDir);
            _envMock.Setup(e => e.ContentRootPath).Returns(_tempDir);
            _controller = new CoursesController(_context, _envMock.Object, _loggerMock.Object);

            // Seed a department
            _context.Departments.Add(new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 100000,
                StartDate = new DateTime(2020, 1, 1)
            });
            _context.SaveChanges();
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
            if (Directory.Exists(_tempDir))
            {
                try { Directory.Delete(_tempDir, true); } catch { }
            }
        }

        private Course CreateCourse(int id = 1001, string title = "Test Course", int credits = 3)
        {
            return new Course { CourseID = id, Title = title, Credits = credits, DepartmentID = 1 };
        }

        private void SeedCourse(Course course)
        {
            _context.Courses.Add(course);
            _context.SaveChanges();
        }

        // --- Index ---

        [Fact]
        public void Index_ReturnsViewWithCourses()
        {
            SeedCourse(CreateCourse(1001, "Intro to CS"));
            SeedCourse(CreateCourse(1002, "Data Structures"));

            var result = _controller.Index() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<System.Collections.Generic.List<Course>>(result.Model);
            Assert.Equal(2, model.Count);
        }

        // --- Details ---

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithCourse()
        {
            var course = CreateCourse(2001, "Physics");
            SeedCourse(course);

            var result = _controller.Details(2001) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal("Physics", model.Title);
            Assert.NotNull(model.Department);
        }

        // --- Create GET ---

        [Fact]
        public void Create_Get_ReturnsViewWithNewCourse()
        {
            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            Assert.IsType<Course>(result.Model);
        }

        // --- Create POST ---

        [Fact]
        public void Create_ValidCourse_NoImage_RedirectsToIndex()
        {
            var course = CreateCourse(3001, "Algorithms");

            var result = _controller.Create(course, null);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(_context.Courses);
        }

        [Fact]
        public void Create_ValidCourse_WithValidImage_SavesImageAndRedirects()
        {
            var course = CreateCourse(3002, "Networks");
            var fileMock = CreateMockFile("test.jpg", 1024);

            var result = _controller.Create(course, fileMock.Object);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            var saved = _context.Courses.Find(3002);
            Assert.NotNull(saved.TeachingMaterialImagePath);
            Assert.StartsWith("/Uploads/TeachingMaterials/", saved.TeachingMaterialImagePath);
        }

        [Fact]
        public void Create_InvalidExtension_ReturnsViewWithError()
        {
            var course = CreateCourse(3003, "OS");
            var fileMock = CreateMockFile("test.exe", 1024);

            var result = _controller.Create(course, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_FileTooLarge_ReturnsViewWithError()
        {
            var course = CreateCourse(3004, "DB");
            var fileMock = CreateMockFile("test.jpg", 6 * 1024 * 1024);

            var result = _controller.Create(course, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_InvalidModel_ReturnsViewWithCourse()
        {
            _controller.ModelState.AddModelError("Title", "Required");
            var course = CreateCourse();

            var result = _controller.Create(course, null) as ViewResult;

            Assert.NotNull(result);
        }

        // --- Edit GET ---

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit((int?)null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_Get_InvalidId_ReturnsNotFound()
        {
            var result = _controller.Edit(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithCourse()
        {
            var course = CreateCourse(4001, "Compilers");
            SeedCourse(course);

            var result = _controller.Edit(4001) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal("Compilers", model.Title);
        }

        // --- Edit POST ---

        [Fact]
        public void Edit_ValidCourse_NoImage_RedirectsToIndex()
        {
            var course = CreateCourse(5001, "AI");
            SeedCourse(course);
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var updated = CreateCourse(5001, "AI Updated");

            var result = _controller.Edit(updated, null);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_InvalidExtension_ReturnsViewWithError()
        {
            var course = CreateCourse(5002, "ML");
            SeedCourse(course);
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var updated = CreateCourse(5002, "ML");
            var fileMock = CreateMockFile("bad.txt", 1024);

            var result = _controller.Edit(updated, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_FileTooLarge_ReturnsViewWithError()
        {
            var course = CreateCourse(5003, "DL");
            SeedCourse(course);
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var updated = CreateCourse(5003, "DL");
            var fileMock = CreateMockFile("big.png", 6 * 1024 * 1024);

            var result = _controller.Edit(updated, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_InvalidModel_ReturnsView()
        {
            _controller.ModelState.AddModelError("Title", "Required");
            var course = CreateCourse(5004, "NLP");

            var result = _controller.Edit(course, null) as ViewResult;

            Assert.NotNull(result);
        }

        // --- Delete GET ---

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithCourse()
        {
            var course = CreateCourse(6001, "Robotics");
            SeedCourse(course);

            var result = _controller.Delete(6001) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal("Robotics", model.Title);
        }

        // --- DeleteConfirmed ---

        [Fact]
        public void DeleteConfirmed_RemovesCourseAndRedirects()
        {
            var course = CreateCourse(7001, "Security");
            SeedCourse(course);

            var result = _controller.DeleteConfirmed(7001);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Null(_context.Courses.Find(7001));
        }

        [Theory]
        [InlineData(".jpg")]
        [InlineData(".jpeg")]
        [InlineData(".png")]
        [InlineData(".gif")]
        [InlineData(".bmp")]
        public void Create_AllowedImageExtensions_AreAccepted(string extension)
        {
            var course = CreateCourse(8000 + Math.Abs(extension.GetHashCode() % 1000), "Test");
            var fileMock = CreateMockFile($"image{extension}", 1024);

            var result = _controller.Create(course, fileMock.Object);

            Assert.IsType<RedirectToActionResult>(result);
        }

        // --- Helpers ---

        private static Mock<IFormFile> CreateMockFile(string fileName, long length)
        {
            var mock = new Mock<IFormFile>();
            mock.Setup(f => f.FileName).Returns(fileName);
            mock.Setup(f => f.Length).Returns(length);
            var stream = new MemoryStream(new byte[Math.Min(length, 1024)]);
            mock.Setup(f => f.CopyTo(It.IsAny<Stream>())).Callback<Stream>(s =>
            {
                stream.Position = 0;
                stream.CopyTo(s);
            });
            return mock;
        }
    }
}

