using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new InstructorsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Instructor CreateInstructor(string firstName = "John", string lastName = "Doe")
        {
            return new Instructor
            {
                FirstMidName = firstName,
                LastName = lastName,
                HireDate = new DateTime(2020, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };
        }

        private void SeedInstructor(Instructor instructor)
        {
            _context.Instructors.Add(instructor);
            _context.SaveChanges();
        }

        private Course SeedCourse(int courseId, string title)
        {
            var dept = _context.Departments.FirstOrDefault();
            if (dept == null)
            {
                dept = new Department { Name = "Test Dept", Budget = 10000, StartDate = new DateTime(2020, 1, 1) };
                _context.Departments.Add(dept);
                _context.SaveChanges();
            }
            var course = new Course { CourseID = courseId, Title = title, Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();
            return course;
        }

        // --- Index ---

        [Fact]
        public void Index_NoSelection_ReturnsViewWithInstructors()
        {
            SeedInstructor(CreateInstructor("Alice", "Smith"));
            SeedInstructor(CreateInstructor("Bob", "Jones"));

            var result = _controller.Index(null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Models.SchoolViewModels.InstructorIndexData>(result.Model);
            Assert.Equal(2, model.Instructors.Count());
        }

        [Fact]
        public void Index_WithInstructorId_PopulatesCourses()
        {
            var instructor = CreateInstructor("Alice", "Smith");
            SeedInstructor(instructor);
            var course = SeedCourse(101, "Intro CS");
            _context.CourseAssignments.Add(new CourseAssignment { InstructorID = instructor.ID, CourseID = course.CourseID });
            _context.SaveChanges();

            var result = _controller.Index(instructor.ID, null) as ViewResult;
            var model = Assert.IsType<Models.SchoolViewModels.InstructorIndexData>(result.Model);

            Assert.NotNull(model.Courses);
            Assert.Single(model.Courses);
        }

        // --- Details ---

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_InvalidId_ReturnsNotFound()
        {
            var result = _controller.Details(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithInstructor()
        {
            var instructor = CreateInstructor("Alice", "Smith");
            SeedInstructor(instructor);

            var result = _controller.Details(instructor.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.Equal("Alice", model.FirstMidName);
        }

        // --- Create GET ---

        [Fact]
        public void Create_Get_ReturnsViewWithNewInstructor()
        {
            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.NotNull(model.CourseAssignments);
        }

        // --- Create POST ---

        [Fact]
        public void Create_ValidInstructor_NoCourses_RedirectsToIndex()
        {
            var instructor = CreateInstructor("Test", "Instructor");

            var result = _controller.Create(instructor, null);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(_context.Instructors);
        }

        [Fact]
        public void Create_ValidInstructor_WithCourses_AddsCourseAssignments()
        {
            var course = SeedCourse(201, "Data Structures");
            var instructor = CreateInstructor("Test", "Prof");

            var result = _controller.Create(instructor, new[] { course.CourseID.ToString() });

            Assert.IsType<RedirectToActionResult>(result);
            var saved = _context.Instructors.First();
            Assert.Single(_context.CourseAssignments.Where(ca => ca.InstructorID == saved.ID));
        }

        [Fact]
        public void Create_InvalidModel_ReturnsView()
        {
            _controller.ModelState.AddModelError("LastName", "Required");
            var instructor = CreateInstructor();

            var result = _controller.Create(instructor, null) as ViewResult;

            Assert.NotNull(result);
        }

        // --- Edit GET ---

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit((int?)null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithInstructor()
        {
            var instructor = CreateInstructor("Alice", "Smith");
            instructor.OfficeAssignment = new OfficeAssignment { Location = "Room 101" };
            SeedInstructor(instructor);

            var result = _controller.Edit(instructor.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.Equal("Alice", model.FirstMidName);
        }

        // --- Delete GET ---

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_Get_InvalidId_ReturnsNotFound()
        {
            var result = _controller.Delete(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithInstructor()
        {
            var instructor = CreateInstructor("Alice", "Smith");
            SeedInstructor(instructor);

            var result = _controller.Delete(instructor.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.Equal("Smith", model.LastName);
        }

        // --- DeleteConfirmed ---

        [Fact]
        public void DeleteConfirmed_RemovesInstructorAndRedirects()
        {
            var instructor = CreateInstructor("Alice", "Smith");
            instructor.OfficeAssignment = new OfficeAssignment { Location = "Room 101" };
            SeedInstructor(instructor);
            var id = instructor.ID;

            var result = _controller.DeleteConfirmed(id);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Empty(_context.Instructors);
        }

        [Fact]
        public void DeleteConfirmed_InstructorAdministeringDept_ClearsDeptAdministrator()
        {
            var instructor = CreateInstructor("Admin", "Person");
            instructor.OfficeAssignment = new OfficeAssignment { Location = "Main Office" };
            SeedInstructor(instructor);

            var dept = new Department
            {
                Name = "Test Dept",
                Budget = 50000,
                StartDate = new DateTime(2020, 1, 1),
                InstructorID = instructor.ID
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            _controller.DeleteConfirmed(instructor.ID);

            var updatedDept = _context.Departments.Find(dept.DepartmentID);
            Assert.Null(updatedDept.InstructorID);
        }
    }
}

