using System;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class DbInitializerTests : IDisposable
    {
        private readonly SchoolContext _context;

        public DbInitializerTests()
        {
            _context = TestDbContextFactory.Create();
        }

        public void Dispose() => _context.Dispose();

        [Fact]
        public void Initialize_EmptyDatabase_SeedsAllEntities()
        {
            DbInitializer.Initialize(_context);

            Assert.Equal(8, _context.Students.CountAsync().Result);
            Assert.Equal(5, _context.Instructors.CountAsync().Result);
            Assert.Equal(4, _context.Departments.CountAsync().Result);
            Assert.Equal(7, _context.Courses.CountAsync().Result);
            Assert.True(_context.Enrollments.CountAsync().Result > 0);
            Assert.True(_context.OfficeAssignments.CountAsync().Result > 0);
            Assert.True(_context.CourseAssignments.CountAsync().Result > 0);
        }

        [Fact]
        public void Initialize_AlreadySeeded_DoesNotDuplicate()
        {
            DbInitializer.Initialize(_context);
            var firstCount = _context.Students.CountAsync().Result;

            DbInitializer.Initialize(_context);
            var secondCount = _context.Students.CountAsync().Result;

            Assert.Equal(firstCount, secondCount);
        }

        [Fact]
        public void Initialize_VerifiesStudentData()
        {
            DbInitializer.Initialize(_context);

            var student = _context.Students.FirstAsync(s => s.LastName == "Alexander").Result;
            Assert.Equal("Carson", student.FirstMidName);
        }

        [Fact]
        public void Initialize_VerifiesInstructorData()
        {
            DbInitializer.Initialize(_context);

            var instructor = _context.Instructors.FirstAsync(i => i.LastName == "Abercrombie").Result;
            Assert.Equal("Kim", instructor.FirstMidName);
        }

        [Fact]
        public void Initialize_VerifiesDepartmentHasAdministrator()
        {
            DbInitializer.Initialize(_context);

            var dept = _context.Departments.Include(d => d.Administrator)
                .FirstAsync(d => d.Name == "English").Result;
            Assert.NotNull(dept.InstructorID);
        }
    }
}

using System;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using Xunit;
using System.Linq;

namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests : IDisposable
    {
        private readonly SchoolContext _context;

        public SchoolContextTests()
        {
            _context = TestDbContextFactory.Create();
        }

        public void Dispose() => _context.Dispose();

        [Fact]
        public void Context_CanAddAndRetrieveStudent()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = new DateTime(2023, 1, 1)
            };
            _context.Students.Add(student);
            _context.SaveChanges();

            var retrieved = _context.Students.Find(student.ID);

            Assert.NotNull(retrieved);
            Assert.Equal("Test", retrieved.FirstMidName);
        }

        [Fact]
        public void Context_CanAddAndRetrieveCourse()
        {
            var dept = new Department
            {
                Name = "Test",
                Budget = 10000,
                StartDate = new DateTime(2020, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course
            {
                CourseID = 9999,
                Title = "Test Course",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var retrieved = _context.Courses.Find(9999);
            Assert.NotNull(retrieved);
            Assert.Equal("Test Course", retrieved.Title);
        }

        [Fact]
        public void Context_CourseAssignment_HasCompositeKey()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Inst",
                HireDate = new DateTime(2020, 1, 1)
            };
            _context.Instructors.Add(instructor);
            var dept = new Department { Name = "D", Budget = 1000, StartDate = new DateTime(2020, 1, 1) };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 5555, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var ca = new CourseAssignment { CourseID = 5555, InstructorID = instructor.ID };
            _context.CourseAssignments.Add(ca);
            _context.SaveChanges();

            var found = _context.CourseAssignments.Find(5555, instructor.ID);
            Assert.NotNull(found);
        }

        [Fact]
        public void Context_Enrollment_RelationshipsWork()
        {
            var student = new Student
            {
                FirstMidName = "S",
                LastName = "T",
                EnrollmentDate = new DateTime(2023, 1, 1)
            };
            _context.Students.Add(student);
            var dept = new Department { Name = "D", Budget = 1000, StartDate = new DateTime(2020, 1, 1) };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 7777, Title = "C", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var enrollment = new Enrollment { StudentID = student.ID, CourseID = 7777, Grade = Grade.A };
            _context.Enrollments.Add(enrollment);
            _context.SaveChanges();

            var retrieved = _context.Enrollments
                .Include(e => e.Student)
                .Include(e => e.Course)
                .First(e => e.EnrollmentID == enrollment.EnrollmentID);

            Assert.Equal("S", retrieved.Student.FirstMidName);
            Assert.Equal("C", retrieved.Course.Title);
            Assert.Equal(Grade.A, retrieved.Grade);
        }
    }
}

