using System;
using System.Linq;
using System.Threading.Tasks;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class DbInitializerTests : IDisposable
    {
        private readonly SchoolContext _context;

        public DbInitializerTests()
        {
            _context = TestDbContextFactory.Create();
        }

        public void Dispose() => _context.Dispose();

        [Fact]
        public async Task Initialize_EmptyDatabase_SeedsAllEntities()
        {
            DbInitializer.Initialize(_context);

            Assert.Equal(8, await _context.Students.CountAsync());
            Assert.Equal(5, await _context.Instructors.CountAsync());
            Assert.Equal(4, await _context.Departments.CountAsync());
            Assert.Equal(7, await _context.Courses.CountAsync());
            Assert.True(await _context.Enrollments.CountAsync() > 0);
            Assert.True(await _context.OfficeAssignments.CountAsync() > 0);
            Assert.True(await _context.CourseAssignments.CountAsync() > 0);
        }

        [Fact]
        public async Task Initialize_AlreadySeeded_DoesNotDuplicate()
        {
            DbInitializer.Initialize(_context);
            var firstCount = await _context.Students.CountAsync();

            DbInitializer.Initialize(_context);
            var secondCount = await _context.Students.CountAsync();

            Assert.Equal(firstCount, secondCount);
        }

        [Fact]
        public async Task Initialize_VerifiesStudentData()
        {
            DbInitializer.Initialize(_context);

            var student = await _context.Students.FirstAsync(s => s.LastName == "Alexander");
            Assert.Equal("Carson", student.FirstMidName);
        }

        [Fact]
        public async Task Initialize_VerifiesInstructorData()
        {
            DbInitializer.Initialize(_context);

            var instructor = await _context.Instructors.FirstAsync(i => i.LastName == "Abercrombie");
            Assert.Equal("Kim", instructor.FirstMidName);
        }

        [Fact]
        public async Task Initialize_VerifiesDepartmentHasAdministrator()
        {
            DbInitializer.Initialize(_context);

            var dept = await _context.Departments.Include(d => d.Administrator)
                .FirstAsync(d => d.Name == "English");
            Assert.NotNull(dept.InstructorID);
        }

        [Fact]
        public void Initialize_SeedsEnrollmentsWithGrades()
        {
            DbInitializer.Initialize(_context);

            var gradedEnrollments = _context.Enrollments.Where(e => e.Grade != null).ToList();
            Assert.True(gradedEnrollments.Count > 0);
        }

        [Fact]
        public void Initialize_SeedsOfficeAssignments()
        {
            DbInitializer.Initialize(_context);

            var offices = _context.OfficeAssignments.ToList();
            Assert.Equal(3, offices.Count);
        }
    }
}

